%%\ Loading up Quadcopter Parameters
% Clears any stale workspace variables from previous runs, then loads the
% physical parameters (thrust coefficient kT, mass M, gravity g, etc.)
% from the pre-computed .mat file.
clear kT quad_m
load('x_quad_params.mat', 'kT', 'quad_m', 'W', 'M', 'g');

%%\ Plot Propeller Performance Curves
% Sweeps propeller speed N from 0 to 10,000 RPM in 1,000 RPM increments
% and plots the resulting thrust using f_prop = kT * N^2 (single propeller).
% The curve is quadratic, confirming that thrust scales with the square
% of rotational speed.
N = 0:1000:10000;          % speed sweep [rpm]
thrust_single = kT * N.^2; % thrust per propeller [N]

figure('Name','Propeller Thrust vs Speed','NumberTitle','off'); %[output:62589e2e]
plot(N, thrust_single, 'LineWidth', 1.5); %[output:62589e2e]
xlabel('Speed (rpm)'); %[output:62589e2e]
ylabel('Thrust (N)'); %[output:62589e2e]
title('Single Propeller Performance Curve'); %[output:62589e2e]
grid minor; %[output:62589e2e]

